node --input-type=module <<'JS'
import {Client} from '@modelcontextprotocol/sdk/client/index.js';
import {StdioClientTransport} from '@modelcontextprotocol/sdk/client/stdio.js';
import {writeFile} from 'node:fs/promises';
const c=new Client({name:'diagram-plan-reader',version:'1'});
await c.connect(new StdioClientTransport({command:'node',args:['--import','tsx','scripts/mapping/mcp.ts','http://127.0.0.1:5193']}));
try {
 const schemas=await c.listTools();
 console.log(JSON.stringify(schemas.tools.filter(t=>['exec','diagram-search','canvas-api-search'].includes(t.name))));
 const docs=await c.callTool({name:'canvas-api-search',arguments:{query:''}});
 console.log(JSON.stringify(docs));
 const canvases=await c.callTool({name:'exec',arguments:{requestId:crypto.randomUUID(),code:'return canvas.list();'}});
 await writeFile('/tmp/create-diagram-plan-canvases.json',JSON.stringify(canvases));
 console.log(JSON.stringify(canvases));
} finally {await c.close();}
JS

