await c.connect(new StdioClientTransport({command:'node',args:['--import','tsx','scripts/mapping/mcp.ts','http://127.0.0.1:5193']}));
try {
 for (const query of ['canvas.attach','nodes.list']) {const r=await c.callTool({name:'canvas-api-search',arguments:{query}});console.log(JSON.stringify(r.structuredContent??r));}
