command:
node --input-type=module <<'JS'
import {writeFile} from 'node:fs/promises';
const base='http://127.0.0.1:5193';
const canvases=await (await fetch(`${base}/api/mapping/agent/canvases`)).json();
const c=canvases[0];
const results=await Promise.allSettled(c.documents.map(async d=>{
 const u=new URL('/api/mapping/live/context/short',base);u.searchParams.set('workspaceInstanceId',c.canvasId);u.searchParams.set('documentId',d.documentId);
 const r=await fetch(u,{signal:AbortSignal.timeout(30000)});const body=await r.json();
 return {name:d.name,documentId:d.documentId,status:r.status,body};
}));
await writeFile('/tmp/create-diagram-plan-short.json',JSON.stringify(results));
for(const r of results) console.log(JSON.stringify(r.status==='fulfilled'?{name:r.value.name,status:r.value.status,keys:Object.keys(r.value.body),preview:JSON.stringify(r.value.body).slice(0,250)}:{error:String(r.reason)}));
JS

