node --input-type=module <<'JS'
import {readFile} from 'node:fs/promises';
const data=JSON.parse(await readFile('/tmp/create-diagram-plan-short.json','utf8'));
for(const {value:c} of data) if(/^(Mapping page|AgentContext|PersistentLayer)/.test(c.name)) {
 console.log('\nCANVAS: '+c.name);
 for(const d of c.body.diagrams) console.log('\nDIAGRAM: '+d.id+'\n'+d.ascii);
 console.log('CONNECTIONS: '+JSON.stringify(c.body.edges.map(e=>({source:e.source,target:e.target,label:e.appearance?.label}))));
}
JS

node --input-type=module <<'JS'
import {readFile} from 'node:fs/promises';
const data=JSON.parse(await readFile('/tmp/create-diagram-plan-short.json','utf8'));
for(const {value:c} of data) if(/^(Canvas domain|Workspace persistence|MappingDocumentController)/.test(c.name)) {
 console.log('\nCANVAS: '+c.name);
 for(const d of c.body.diagrams) if(!c.name.startsWith('Canvas domain') || /^\[([BDG])\]/.test(d.ascii)) console.log('\nDIAGRAM: '+d.id+'\n'+d.ascii);
}
JS
